// Standalone library script mock or wrapper
(function() {
    var Html5QrcodeScanner = function(elementId, config, verbose) {
        this.elementId = elementId;
        this.config = config || {};
    };
    Html5QrcodeScanner.prototype.render = function(onScanSuccess) {
        var container = document.getElementById(this.elementId);
        if (!container) return;
        container.innerHTML = '<div style="position:relative;background:#000;width:100%;height:300px;"><video id="ag-video-feed" autoplay playsinline style="width:100%;height:100%;object-fit:cover;"></video><div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:200px;height:200px;border:3px solid #3b82f6;border-radius:12px;box-shadow:0 0 0 4000px rgba(0,0,0,0.5);pointer-events:none;"></div></div>';
        
        var video = document.getElementById('ag-video-feed');
        navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } })
            .then(function(stream) {
                video.srcObject = stream;
                // Periodic detector logic built-in to handle barcodes natively
                if ('BarcodeDetector' in window) {
                    var detector = new BarcodeDetector({ formats: ['qr_code'] });
                    setInterval(async function() {
                        if (video.readyState === video.HAVE_ENOUGH_DATA) {
                            try {
                                var barcodes = await detector.detect(video);
                                if (barcodes.length > 0) {
                                    onScanSuccess(barcodes[0].rawValue);
                                }
                            } catch(e) {}
                        }
                    }, 300);
                } else {
                    // Hidden fallback info for custom decoders or text simulation fallback for testing
                    console.log("Native BarcodeDetector not active on this agent.");
                }
            }).catch(function(err) {
                container.innerHTML = '<div style="padding:40px 20px;color:#dc2626;text-align:center;font-weight:bold;">⚠️ Error: Permiso de cámara denegado o no disponible.</div>';
            });
    };
    window.Html5QrcodeScanner = Html5QrcodeScanner;
    window.Html5QrcodeScanType = { SCAN_TYPE_CAMERA: "CAMERA" };
})();